class MaxHeap {
  private a: number[] = [];
  get size(): number { return this.a.length; }

  push(x: number): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] >= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }

  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] > a[m]) m = l;
        if (r < a.length && a[r] > a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function minSlots(tasks: string[], n: number): number {
  const count = new Map<string, number>();
  for (const t of tasks) count.set(t, (count.get(t) ?? 0) + 1);
  const heap = new MaxHeap();
  for (const c of count.values()) heap.push(c);
  const wait: [number, number][] = []; // [jobs left, slot when the cooldown ends]
  let head = 0, time = 0;
  while (heap.size || head < wait.length) {
    time++;
    if (heap.size) {
      const left = heap.pop() - 1;
      if (left) wait.push([left, time + n]);
    } else {
      time = wait[head][1]; // nothing can run: skip the idle slots
    }
    if (head < wait.length && wait[head][1] === time) heap.push(wait[head++][0]);
  }
  return time;
}

