class Solution:
    def minSlots(self, tasks: List[str], n: int) -> int:
        heap = [-c for c in Counter(tasks).values()]  # negated: heapq is a min-heap
        heapq.heapify(heap)
        wait = deque()  # (negated jobs left, slot when the cooldown ends)
        time = 0
        while heap or wait:
            time += 1
            if heap:
                left = heapq.heappop(heap) + 1  # one job done
                if left:
                    wait.append((left, time + n))
            else:
                time = wait[0][1]  # nothing can run: skip the idle slots
            if wait and wait[0][1] == time:
                heapq.heappush(heap, wait.popleft()[0])
        return time

